using System;using System.Threading;using System.Threading.Tasks;using CodexForVS.Client;using Newtonsoft.Json.Linq;using Xunit;
namespace CodexForVS.Tests;
public sealed class CodexProcessLifecycleTests
{
 [Fact]public async Task ClientStartsInjectedProcessOnlyOnce(){var process=new FakeProcess();using var client=new CodexAppServerClient(process);await client.StartAsync(CancellationToken.None);await client.StartAsync(CancellationToken.None);Assert.Equal(1,process.StartCount);}
 [Fact]public async Task ExitIsReportedWithoutDisposingExternalProcess(){var process=new FakeProcess();using var client=new CodexAppServerClient(process);var seen=new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);client.EventReceived+=(_,e)=>{if(e.Kind=="error")seen.TrySetResult(e.Text);};await client.StartAsync(CancellationToken.None);process.RaiseExit();Assert.Contains("exited",await seen.Task);Assert.False(process.Disposed);}
 [Fact]public async Task StartupFailureDoesNotMarkProcessRunning(){var process=new FakeProcess{Failure=new InvalidOperationException("codex not found")};using var client=new CodexAppServerClient(process);await Assert.ThrowsAsync<InvalidOperationException>(()=>client.StartAsync(CancellationToken.None));Assert.False(process.IsRunning);}
 private sealed class FakeProcess:ICodexProcess{public int StartCount;public bool Disposed;public Exception? Failure;public event EventHandler? Exited;public event EventHandler<string>? StandardErrorReceived{add{}remove{}}public bool IsRunning{get;private set;}public IJsonRpcTransport Start(){StartCount++;if(Failure!=null)throw Failure;IsRunning=true;return new FakeTransport();}public void RaiseExit(){IsRunning=false;Exited?.Invoke(this,EventArgs.Empty);}public void Dispose(){Disposed=true;IsRunning=false;}}
 private sealed class FakeTransport:IJsonRpcTransport{public event EventHandler<JObject>? MessageReceived{add{}remove{}}public event EventHandler<Exception>? Faulted{add{}remove{}}public Task<JObject> RequestAsync(string method,JObject p,CancellationToken t){if(method=="account/read")return Task.FromResult(new JObject{{"account",new JObject()}});return Task.FromResult(new JObject());}public Task NotifyAsync(string m,JObject p,CancellationToken t)=>Task.CompletedTask;public Task RejectAsync(JToken id,CancellationToken token) => Task.CompletedTask;
        public Task RespondAsync(JToken id,JObject r,CancellationToken t)=>Task.CompletedTask;public void Dispose(){}}
}
